const pool = mysql.createPool({
  host: `localhost`,
  password: `1234`,
  port: 3306,
  user: `root`,
  database: `class2`,
});

const server = http.createServer(async (req, res) => {
  res.setHeader(`content-type`, `text/plain; charset=utf-8`);
  const { url } = req;
  const [students] = await pool.execute(
    `select name, gender, age from students`,
  );
  if (url == `/random`) {
    const stu10000 = Array(10000)
      .fill(0)
      .map((x) => faker.person.fullName());
    if (students.length < 10000) {
      console.log(`학생 추가`);
      stu10000.forEach(
        async (x, i) =>
          await pool.execute(
            `insert into students (name, gender, age) values ("${x}", "${i % 3 ? `M` : `F`}", 20)`,
          ),
        // pool.query(`query ? `, [datas]);
      );
    }
    res.end(JSON.stringify(stu10000));
  } else
    res.end(
      students.reduce(
        (a, c, i) =>
          a +
          `${
            c.name.length < 3
              ? Array(3 - c.name.length)
                  .fill(`ㅤ`)
                  .reduce((x, y) => x + y, ``) + c.name
              : c.name
          }(${c.age} | ${c.gender == `M` ? `남` : `여`})${(i + 1) % 5 ? `,\t` : `\n\n`}`,
        ``,
      ),
    );
});

server.listen(3000, () => {
  console.log(`학생부 열람`);
});
